<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_Staff_Actions{
 public static function init():void{add_action('admin_post_nvc_followup_action',[self::class,'handle']);}
 public static function handle():void{if(!current_user_can('nvconsult_manage_applications'))wp_die(esc_html__('Access denied.','nvconsult-core'));check_admin_referer('nvc_followup_action');$id=absint($_POST['application_id']??0);$action=sanitize_key($_POST['case_action']??'');if(!$id||get_post_type($id)!=='nv_application')wp_die(esc_html__('Invalid application.','nvconsult-core'));$old=(string)get_post_meta($id,'_nvconsult_followup_date',true);$next='';if($action==='complete'){$next=sanitize_text_field(wp_unslash($_POST['next_followup']??''));if($next&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$next))$next='';}elseif($action==='snooze_1')$next=date('Y-m-d',strtotime(current_time('Y-m-d').' +1 day'));elseif($action==='snooze_3')$next=date('Y-m-d',strtotime(current_time('Y-m-d').' +3 days'));elseif($action==='snooze_7')$next=date('Y-m-d',strtotime(current_time('Y-m-d').' +7 days'));else wp_die(esc_html__('Invalid action.','nvconsult-core'));if($next)update_post_meta($id,'_nvconsult_followup_date',$next);else delete_post_meta($id,'_nvconsult_followup_date');$history=(array)get_post_meta($id,'_nvconsult_followup_history',true);$history[]=['action'=>$action,'previous'=>$old,'next'=>$next,'user_id'=>get_current_user_id(),'time'=>current_time('mysql')];if(count($history)>100)$history=array_slice($history,-100);update_post_meta($id,'_nvconsult_followup_history',$history);wp_safe_redirect(wp_get_referer()?:admin_url('edit.php?post_type=nv_application&page=nvconsult-operations'));exit;}
 public static function controls(int$id):void{$url=admin_url('admin-post.php');echo'<form method="post" action="'.esc_url($url).'" style="display:flex;gap:5px;align-items:center;flex-wrap:wrap">';wp_nonce_field('nvc_followup_action');echo'<input type="hidden" name="action" value="nvc_followup_action"><input type="hidden" name="application_id" value="'.absint($id).'"><select name="case_action"><option value="complete">'.esc_html__('Complete','nvconsult-core').'</option><option value="snooze_1">'.esc_html__('Snooze 1d','nvconsult-core').'</option><option value="snooze_3">'.esc_html__('Snooze 3d','nvconsult-core').'</option><option value="snooze_7">'.esc_html__('Snooze 7d','nvconsult-core').'</option></select><input type="date" name="next_followup" title="'.esc_attr__('Next follow-up after completion','nvconsult-core').'"><button class="button button-small" type="submit">'.esc_html__('Apply','nvconsult-core').'</button></form>';}
}
